    "statement_index": 12,
    "statement": {
      "subject": {
        "value": "ice",
        "evidence": [
          {
            "segment": "text",
            "quote": "ice",
            "occurrence": 1
          }
        ]
      },
      "predicate": {
        "value": "becameThickIn",
        "evidence": [
          {
            "segment": "text",
            "quote": "In December 1939 the ice became so thick",
            "occurrence": 1
